script:
files = repo.list("src")
out = {"listing": files, "files": {}}
for f in repo.list("src"):
    if f.endswith("/"):
        sub = repo.list("src/" + f)
        for s in sub:
            if s.endswith(".py"):
                p = "src/" + f + s
                out["files"][p] = repo.read(p)
    elif f.endswith(".py"):
        p = "src/" + f
        out["files"][p] = repo.read(p)

# also search case-insensitively for fixme variants and other markers
variants = repo.search("(?i)fixme", glob = "src/**")
out["case_insensitive"] = [{"path": v.path, "line": v.line, "text": v.text.strip()} for v in variants]
result(out)
